sealed class ContractException: kotlin.Exception() {
    
    class UnsupportedSchemaVersion(
        
        val `version`: kotlin.String
        ) : ContractException() {
        override val message
            get() = "version=${ `version` }"
    }
    
    class InvalidId(
        
        val `field`: kotlin.String, 
        
        val `value`: kotlin.String
        ) : ContractException() {
        override val message
            get() = "field=${ `field` }, value=${ `value` }"
    }
    
    class EmptyField(
        
        val `name`: kotlin.String
        ) : ContractException() {
        override val message
            get() = "name=${ `name` }"
    }
    
    class TargetFieldMissing(
        
        val `name`: kotlin.String
        ) : ContractException() {
        override val message
            get() = "name=${ `name` }"
    }
    
    class PayloadMismatch(
        
        val `kind`: SessionKind, 
        
        val `expected`: kotlin.String
        ) : ContractException() {
        override val message
            get() = "kind=${ `kind` }, expected=${ `expected` }"
    }
    
    class UnsupportedAlgorithm(
        
        val `algorithm`: kotlin.String
        ) : ContractException() {
        override val message
            get() = "algorithm=${ `algorithm` }"
    }
    
    class MissingExpiry(
        ) : ContractException() {
        override val message
            get() = ""
    }
    
    class MissingScope(
        ) : ContractException() {
        override val message
            get() = ""
    }
    
    class PlaceholderSignature(
        ) : ContractException() {
        override val message
            get() = ""
    }
    
    class InvalidModuleHash(
        ) : ContractException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ContractException> {
        override fun lift(error_buf: RustBuffer.ByValue): ContractException = FfiConverterTypeContractError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeContractError : FfiConverterRustBuffer<ContractException> {
    override fun read(buf: ByteBuffer): ContractException {
        

        return when(buf.getInt()) {
            1 -> ContractException.UnsupportedSchemaVersion(
                FfiConverterString.read(buf),
                )
            2 -> ContractException.InvalidId(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> ContractException.EmptyField(
                FfiConverterString.read(buf),
                )
            4 -> ContractException.TargetFieldMissing(
                FfiConverterString.read(buf),
                )
            5 -> ContractException.PayloadMismatch(
                FfiConverterTypeSessionKind.read(buf),
                FfiConverterString.read(buf),
                )
            6 -> ContractException.UnsupportedAlgorithm(
                FfiConverterString.read(buf),
                )
            7 -> ContractException.MissingExpiry()
            8 -> ContractException.MissingScope()
            9 -> ContractException.PlaceholderSignature()
            10 -> ContractException.InvalidModuleHash()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ContractException): ULong {
        return when(value) {
            is ContractException.UnsupportedSchemaVersion -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`version`)
            )
            is ContractException.InvalidId -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`field`)
                + FfiConverterString.allocationSize(value.`value`)
            )
            is ContractException.EmptyField -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`name`)
            )
            is ContractException.TargetFieldMissing -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`name`)
            )
            is ContractException.PayloadMismatch -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeSessionKind.allocationSize(value.`kind`)
                + FfiConverterString.allocationSize(value.`expected`)
            )
            is ContractException.UnsupportedAlgorithm -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`algorithm`)
            )
            is ContractException.MissingExpiry -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ContractException.MissingScope -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ContractException.PlaceholderSignature -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is ContractException.InvalidModuleHash -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: ContractException, buf: ByteBuffer) {
        when(value) {
            is ContractException.UnsupportedSchemaVersion -> {
                buf.putInt(1)
                FfiConverterString.write(value.`version`, buf)
                Unit
            }
            is ContractException.InvalidId -> {
                buf.putInt(2)
                FfiConverterString.write(value.`field`, buf)
                FfiConverterString.write(value.`value`, buf)
                Unit
            }
            is ContractException.EmptyField -> {
                buf.putInt(3)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
            is ContractException.TargetFieldMissing -> {
                buf.putInt(4)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
            is ContractException.PayloadMismatch -> {
                buf.putInt(5)
                FfiConverterTypeSessionKind.write(value.`kind`, buf)
                FfiConverterString.write(value.`expected`, buf)
                Unit
            }
            is ContractException.UnsupportedAlgorithm -> {
                buf.putInt(6)
                FfiConverterString.write(value.`algorithm`, buf)
                Unit
            }
            is ContractException.MissingExpiry -> {
                buf.putInt(7)
                Unit
            }
            is ContractException.MissingScope -> {
                buf.putInt(8)
                Unit
            }
            is ContractException.PlaceholderSignature -> {
                buf.putInt(9)
                Unit
            }
            is ContractException.InvalidModuleHash -> {
                buf.putInt(10)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





